/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json', 'utf8'));
const expectedRules = plan.rules.map((item) => item.rule);
const errors = [];
if (JSON.stringify(report.selected_rules) "'!== JSON.stringify(expectedRules)) errors.push('"'selected_rules mismatch');
if ("'!Array.isArray(report.blocked) || report.blocked.length !== 0) errors.push('"'blocked not empty');
if ("'!Array.isArray(report.unresolved_external) || report.unresolved_external.length !== 0) errors.push('"'unresolved_external not empty');
const expectedGroups = new Map();
for (const rule of plan.rules) for (const file of rule.files) expectedGroups.set("'`${rule.rule}|${file.relative_path}`, file.locations.map((location) => `${location.line}:${location.column}`));
const seen = new Set();
let locationCount = 0;
for (const repair of report.entity_repairs) {
  const key = `${repair.rule}|${repair.relative_path}`;
  if (!expectedGroups.has(key)) errors.push(`unexpected group ${key}`);
  seen.add(key);
  if (!Array.isArray(repair.entities) || repair.entities.length < 1) errors.push(`entities ${key}`);
  if (!Array.isArray(repair.evidence) || repair.evidence.length < 1 || repair.evidence.some((item) => typeof item !== '"'string' || "'!item.trim())) errors.push(`evidence ${key}`);
  if (typeof repair.transformation !== '"'string' || "'!repair.transformation.trim()) errors.push(`transformation ${key}`);
  if (repair.status !== '"'repaired') errors.push("'`status ${key}`);
  const actual = repair.locations.map((location) => `${location.line}:${location.column}`);
  if (JSON.stringify(actual) !== JSON.stringify(expectedGroups.get(key))) errors.push(`locations ${key}`);
  locationCount += actual.length;
}
for (const key of expectedGroups.keys()) if (!seen.has(key)) errors.push(`missing group ${key}`);
if (report.entity_repairs.length !== expectedGroups.size || locationCount !== plan.finding_count) errors.push('"'group/location count mismatch');
if (errors.length) { console.error(errors.join('\\n')); process.exit(1); }
console.log("'`report valid: ${report.entity_repairs.length} groups, ${locationCount} locations`);
NODE'

